    'RegisterSimpleRisk'=>'Đăng ký SimpleRisk',
    'RegistrationText'=>'Các phiên bản SimpleRisk đã đăng ký sẽ ngay lập tức được cấp quyền truy cập vào các Extra Nâng cấp (Upgrade) và Secure Controls Framework (SCF).  Extra Nâng cấp cung cấp khả năng sao lưu và nâng cấp phiên bản SimpleRisk của bạn chỉ bằng một cú nhấp chuột.  Extra Secure Controls Framework (SCF) cung cấp một khung kiểm soát chung được tích hợp vào chức năng Quản trị của SimpleRisk.  Khi đăng ký SimpleRisk, thông tin đăng ký của bạn sẽ được gửi đến một máy chủ do SimpleRisk lưu trữ.  Thông tin đăng ký được cung cấp sẽ được SimpleRisk sử dụng để thông báo cho khách hàng về các bản phát hành mới và các bản cập nhật an ninh.  Việc đăng ký SimpleRisk sẽ đồng nghĩa với việc bạn đồng ý nhận các thông tin tiếp thị của chúng tôi, nhưng bạn có thể từ chối bất cứ lúc nào bằng liên kết hủy đăng ký trong các thông tin đó.  SimpleRisk tôn trọng quyền riêng tư của khách hàng và thông tin được cung cấp cho chúng tôi thông qua quy trình đăng ký SimpleRisk sẽ không bao giờ bị bán cho bên thứ ba.',
