    'Maintenance'                         => 'Bảo trì',

    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Cấu hình các cài đặt toàn hệ thống: URL cơ sở, an ninh, ngôn ngữ mặc định, múi giờ, giá trị mặc định về điểm rủi ro, và nhiều hơn nữa.',
    'SettingsPreferencesDesc'             => 'Giá trị mặc định và các tùy chọn hành vi trên toàn SimpleRisk: ngôn ngữ, múi giờ, trạng thái kiểm toán, yêu cầu ánh xạ rủi ro, các nút bật/tắt hành vi giao diện, và các mục tương tự.',
    'SettingsFileUploadDesc'              => 'Các loại tệp được phép tải lên và giới hạn kích thước cho các trường tệp đính kèm khác nhau.',
    'SettingsMailDesc'                    => 'Cấu hình SMTP cho thông báo email gửi đi, bao gồm giao thức truyền tải, máy chủ, xác thực và địa chỉ trả lời.',
    'SettingsBackupsDesc'                 => 'Cấu hình thời gian lưu giữ bản sao lưu, lịch trình và liên kết tải xuống cho các bản sao lưu cơ sở dữ liệu SimpleRisk.',
    'SettingsSecurityDesc'                => 'Các cài đặt an ninh về xác thực, phiên làm việc, chính sách mật khẩu, URL cơ sở và API.',
    'SettingsLoggingDesc'                 => 'Cấu hình nhật ký gỡ lỗi và kiểm toán: các mức nhật ký, thời gian lưu giữ và vị trí của các tệp nhật ký.',
    'HealthCheckDesc'                     => 'Chẩn đoán trạng thái hệ thống: phiên bản PHP, phần mở rộng, quyền tệp, kết nối cơ sở dữ liệu, lịch cron và các kích hoạt Extra.',
    'AnnouncementsDesc'                   => 'Soạn thảo và quản lý các thông báo dạng banner hiển thị cho tất cả người dùng.',
    'RegisterAndUpgradeDesc'              => 'Đăng ký bản cài đặt SimpleRisk của bạn, nhập hoặc gia hạn khóa đăng ký, và kích hoạt nâng cấp Core/Extra chỉ bằng một cú nhấp chuột.',
    'QueueMonitorDesc'                    => 'Kiểm tra hàng đợi các tác vụ nền: các tác vụ đang chờ xử lý, đang thực hiện và bị lỗi.',
    'ExtrasDesc'                          => 'Kích hoạt, vô hiệu hóa và cấu hình SimpleRisk Extras (các tiện ích bổ sung trả phí).',
    'ArtificialIntelligenceExtraDesc'     => 'Extra Trí tuệ nhân tạo cung cấp khả năng phân tích rủi ro nâng cao (bao gồm các đánh giá FAIR) và tài liệu được tùy chỉnh.',
    'CustomizationExtraDesc'              => 'Extra Tùy chỉnh cho phép thêm và xóa các loại trường khác nhau và tạo động các mẫu trang tùy chỉnh.',
    'NotificationExtraDesc'               => 'Tiện ích Email Notification Extra cho phép SimpleRisk gửi thông báo qua email khi rủi ro được gửi, sửa đổi hoặc được xử lý theo bất kỳ cách nào khác. Tiện ích này cũng có thể được thêm vào dưới dạng một tập lệnh theo lịch trình để gửi lời nhắc định kỳ khi rủi ro sẵn sàng để được quản lý xem xét. Trong sản phẩm SimpleRisk Core, nếu không có tiện ích này, sẽ không có thông báo nào được gửi ra ngoài công cụ.',
    'VulnerabilityManagementExtraDesc'    => 'Extra Quản lý Lỗ hổng cung cấp cho khách hàng khả năng tích hợp phiên bản SimpleRisk của họ với Qualys, Tenable.io hoặc Rapid7 Nexpose/InsightVM và nhập cả dữ liệu tài sản lẫn dữ liệu lỗ hổng vào SimpleRisk. Từ đó, bạn có thể chọn các trang web muốn bao phủ, xác định điểm lỗ hổng nào cần được nhập và phân loại ưu tiên những lỗ hổng nào được chuyển thành rủi ro để theo dõi.',
    'IncidentManagementExtraDesc'         => 'Extra Quản lý Sự cố dựa trên Hướng dẫn Xử lý Sự cố An ninh Máy tính NIST 800-61 và cung cấp các khả năng quản lý sự cố ngay trong hệ thống SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Đổi tên các thuật ngữ của SimpleRisk (Rủi ro, Tài sản, Khung, v.v.) trên toàn bộ giao diện người dùng.',
    'RiskConfigurationDesc'               => 'Cấu hình các quy tắc tính điểm rủi ro: các mức, khẩu vị rủi ro, ngưỡng SLA, và các công thức rủi ro cổ điển / đóng góp.',
    'RiskAndThreatCatalogDesc'            => 'Duy trì danh mục các giá trị rủi ro và mối đe dọa được sử dụng trong các menu thả xuống.',
    'AddAndRemoveValuesDesc'              => 'Quản lý các giá trị trong menu thả xuống cho các trường rủi ro: vị trí, nguồn gốc, danh mục, nhóm, công nghệ, v.v.',
    'AssetValuationDesc'                  => 'Cấu hình thang định giá tài sản và các giá trị định giá ghi đè cho từng tài sản.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Thêm, chỉnh sửa, vô hiệu hóa và đặt lại người dùng; quản lý chính sách mật khẩu.',
    'RoleManagementDesc'                  => 'Xác định các vai trò và quyền hạn mà mỗi vai trò được cấp.',
    'TeamManagementDesc'                  => 'Tạo và quản lý các nhóm được dùng để lọc khả năng hiển thị bản ghi.',
    'SeparationExtraDesc'                 => 'Extra Phân tách theo Nhóm giới hạn việc xem rủi ro chỉ cho những người dùng là thành viên của nhóm được giao rủi ro đó. Trong sản phẩm SimpleRisk Core, nếu không có Extra này, mỗi người dùng đều có thể xem mọi rủi ro.',
    'CustomAuthenticationExtraDesc'       => 'Gói Custom Authentication Extra hỗ trợ xác thực Active Directory và SAML. Trong sản phẩm SimpleRisk Core, nếu không có gói Extra này, lựa chọn duy nhất là tạo người dùng mới trong kho lưu trữ danh tính SimpleRisk.',
    'EncryptionExtraDesc'                 => 'Extra Cơ sở dữ liệu được mã hóa tạo ra một khóa mã hóa AES-256 bit ngẫu nhiên, sau đó dùng khóa đó để mã hóa văn bản nhạy cảm trước khi chèn vào cơ sở dữ liệu SimpleRisk. Điều này ngăn bất kỳ ai xem hoặc sửa đổi dữ liệu mà không sử dụng trực tiếp ứng dụng SimpleRisk.',
    'OrganizationManagementDesc'          => 'Extra Phân cấp Tổ chức cho phép xác định nhiều Đơn vị kinh doanh, mỗi đơn vị có thể bao gồm số lượng nhóm bất kỳ. Sau đó người dùng có thể được giao vào một hoặc nhiều nhóm thuộc các Đơn vị kinh doanh khác nhau. Điều này ảnh hưởng đến khả năng của người dùng trong việc xem và sử dụng các nhóm, người dùng và tài sản mà họ không liên quan.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Xóa hàng loạt rủi ro. Hãy sử dụng thận trọng — việc xóa là vĩnh viễn.',
    'AuditTrailDesc'                      => 'Tìm kiếm và xuất nhật ký kiểm toán hệ thống về các hành động của người dùng.',
    'ImportExportExtraDesc'               => 'Extra Nhập-Xuất cung cấp khả năng nhập dữ liệu vào SimpleRisk bằng cách ánh xạ các trường trong tệp CSV với các trường trong cơ sở dữ liệu SimpleRisk. Extra này có thể được dùng để nhập kết quả kiểm toán từ bảng tính của bên thứ 3, kết quả quét lỗ hổng từ công cụ khác, tài sản từ CMDB của bạn, và nhiều hơn nữa. Extra này cũng cung cấp khả năng xuất các tệp CSV từ SimpleRisk chứa Rủi ro, Giảm nhẹ, Xem xét, hoặc báo cáo Kết hợp của cả ba.',
    'JiraExtraDesc'                       => 'Extra Tích hợp Jira cung cấp cho người dùng khả năng tích hợp hai chiều với một phiên bản Jira. Extra này cho phép kết nối các rủi ro với các vấn đề Jira, cũng như đồng bộ dữ liệu, trạng thái và bình luận của chúng.',
    'APIExtraDesc'                        => 'API Extra cho phép khách hàng sử dụng API RESTful để tạo các tương tác theo kịch bản với các ứng dụng khác nhằm đạt được khả năng tự động hóa nâng cao và tận dụng cơ sở hạ tầng hiện có.',
    'AdvancedSearchExtraDesc'             => "Chức năng Tìm kiếm Nâng cao (Advanced Search Extra) biến hộp tìm kiếm trên thanh công cụ phía trên thành một công cụ tìm kiếm duy nhất bao gồm các rủi ro, khuôn khổ, kiểm soát, tài liệu, ngoại lệ, kiểm thử, kiểm toán, tài sản và nhóm tài sản, với một trang Tìm kiếm đầy đủ để xem xét các kết quả. Chức năng này chỉ hiển thị các bản ghi mà người dùng được phép xem.",
    'AssessmentsExtraDesc'                => 'Extra Đánh giá Rủi ro cung cấp cho người dùng khả năng xác định các liên hệ, tạo câu hỏi (bao gồm logic), tập hợp nhiều câu hỏi bằng mẫu bảng câu hỏi, tạo bảng câu hỏi và gửi cho các liên hệ, xem kết quả bảng câu hỏi, thêm rủi ro dựa trên các kết quả đó, và so sánh kết quả theo thời gian, nhập và xuất các đánh giá được tùy chỉnh bên ngoài, cũng như xem xét nhật ký kiểm toán đánh giá rủi ro.',
    'ActiveAssessmentsDesc'               => 'Xem và quản lý các đánh giá hiện đang được thực hiện.',
    'WorkflowsExtraDesc'                  => 'Tiện ích Workflows Extra cung cấp một công cụ quản lý quy trình làm việc trực quan, dựa trên sự kiện, tự động hóa các hành động quản lý rủi ro khi xảy ra các sự kiện trong SimpleRisk. Bạn có thể thiết kế các quy trình làm việc được kích hoạt khi có thay đổi — chẳng hạn như rủi ro được gửi, cập nhật hoặc xem xét — để định tuyến phê duyệt, phân công công việc và duy trì quy trình hoạt động mà không cần can thiệp thủ công.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => "Secure Controls Framework (SCF) Extra là sự tích hợp trực tiếp giữa Secure Controls Framework và SimpleRisk. Nó nhập danh mục các biện pháp kiểm soát của SCF và các ánh xạ của chúng trên nhiều khuôn khổ tuân thủ và an ninh mạng vào chức năng Quản trị của SimpleRisk, cho phép bạn áp dụng các khuôn khổ cần thiết và quản lý các biện pháp kiểm soát mà không cần phải tự xây dựng chúng.",

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Chuyển đổi các cột ngày xem xét kiểu varchar cũ sang kiểu dữ liệu ngày tháng phù hợp. Chỉ hiển thị khi cần thiết.',
    'DatabaseUpgradeDesc'                 => 'Kích hoạt thủ công quy trình nâng cấp cơ sở dữ liệu SimpleRisk.',

