    'EncryptionBackupStateRestoring'        => 'Quá trình khôi phục đang được tiến hành.',
    'EncryptionNoBackupAvailable'           => 'Hiện tại không có bản sao lưu trước khi kích hoạt nào được lưu trữ. Bản sao lưu được tạo khi bắt đầu mỗi lần kích hoạt và sẽ bị ghi đè bởi bất kỳ lần kích hoạt hoặc hủy kích hoạt nào sau đó.',
    'EncryptionRestoreCtaHelp'              => 'Chọn mục này nếu quá trình xác thực tìm thấy vấn đề và bạn cần quay lại trạng thái trước khi mã hóa.',
    'EncryptionRestoreTitle'                => 'Khôi phục từ bản sao lưu?',
    'EncryptionRestoreBodyWhy'              => 'Quay lại bản chụp trước khi mã hóa được lưu ở thời điểm bắt đầu lần kích hoạt gần nhất. Chọn mục này nếu quá trình xác thực sau kích hoạt tìm thấy vấn đề và bạn cần từ bỏ mã hóa.',
    'EncryptionRestoreBodyWhat'             => 'Mỗi hàng được ghi vào cơ sở dữ liệu sau khi tạo bản sao lưu sẽ bị mất vĩnh viễn — bao gồm các rủi ro, biện pháp giảm nhẹ, các mục nhật ký kiểm toán và mọi thay đổi khác được thực hiện kể từ khi kích hoạt. Extra Cơ sở dữ liệu được mã hóa sẽ bị hủy kích hoạt trong quá trình khôi phục.',
    'EncryptionDeleteBackupCta'             => 'Xóa bản sao lưu trước khi mã hóa',
    'EncryptionDeleteBackupCtaHelp'         => 'Chọn mục này khi quá trình xác thực sau mã hóa đã hoàn thành. Việc xóa bản chụp chưa được mã hóa là điều giúp mã hóa thực sự có tác dụng bảo vệ.',
    'EncryptionDeleteBackupTitle'           => 'Xóa bản sao lưu trước khi mã hóa?',
    'EncryptionDeleteBackupBodyWhy'         => 'Xóa bản sao dữ liệu chưa mã hóa được lưu lại khi bắt đầu lần kích hoạt gần nhất. Việc giữ bản sao này vô thời hạn sẽ làm mất đi mục đích của việc mã hóa — bất kỳ ai có quyền truy cập cơ sở dữ liệu đều có thể đọc được bản sao trước khi mã hóa.',
    'EncryptionDeleteBackupBodyWhat'        => 'Bản sao lưu trong cơ sở dữ liệu sẽ bị xóa ngay lập tức. Bạn sẽ không thể sử dụng chức năng Khôi phục từ bản sao lưu để đưa cơ sở dữ liệu trở lại trạng thái trước khi mã hóa nữa. Nếu sau này bạn phát hiện sự cố với mã hóa, phương án phục hồi duy nhất của bạn sẽ là khôi phục lại cơ sở dữ liệu từ các bản sao lưu hoạt động.',
