    'UserImportPasswordsUnavailable' => 'Không thể hiển thị các mật khẩu tạm thời nữa. Chúng chỉ được hiển thị một lần, chỉ cho quản trị viên đã bắt đầu quá trình nhập và chỉ trong tab trình duyệt đã bắt đầu quá trình đó, và SimpleRisk không lưu giữ bất cứ thứ gì có thể hiển thị lại chúng. Hãy đặt mật khẩu mới cho từng người dùng mới bằng cách chỉnh sửa người dùng đó.',
