    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'Bật HTTP Strict Transport Security (HSTS)',
    'EnableHSTSHelp' => 'Yêu cầu trình duyệt chỉ kết nối với SimpleRisk qua HTTPS trong thời gian tối đa (max age) bên dưới. Chỉ bật tính năng này sau khi HTTPS hoạt động ổn định trên trang web này: các trình duyệt đã nhận tiêu đề này sẽ từ chối HTTP thuần, và chứng chỉ bị lỗi không thể bỏ qua cho đến khi max age hết hạn. Hãy bắt đầu với max age ngắn, chẳng hạn 300 giây, và tăng lên khi HTTPS đã được xác minh.',
    'HSTSMaxAge' => 'HSTS Max Age (giây)',
    'HSTSMaxAgeInvalid' => 'HSTS max age phải là một số nguyên giây trong khoảng từ 0 đến 63072000.',
    'HSTSIncludeSubdomains' => 'Áp dụng HSTS cho tất cả miền con',
