    'ControlIdLegacyDatabaseId' => 'Mã định danh biện pháp kiểm soát (mã định danh cơ sở dữ liệu, xuất dữ liệu cũ)',
    'ControlIdLegacyColumnNotice' => 'Tệp này sử dụng cột ID biện pháp kiểm soát cũ, chứa các ID cơ sở dữ liệu thô thay vì các ID mà SimpleRisk hiển thị. Các ID đã được khớp với ID cơ sở dữ liệu. Hãy xuất lại các biện pháp kiểm soát để nhận được các ID được hiển thị (cột "Mã định danh biện pháp kiểm soát (như hiển thị)") cho các lần nhập sau.',
    'ControlIdLegacyNotFound' => 'Đã bỏ qua hàng: không có kiểm soát nào có ID cơ sở dữ liệu "{$id}".',
    'ControlIdHeaderIsLegacy' => 'Không có gì được nhập. Cột được ánh xạ tới "Mã định danh biện pháp kiểm soát (như hiển thị)" có tiêu đề là "ID biện pháp kiểm soát", đây là cách các biện pháp kiểm soát được xuất từ phiên bản cũ hơn đặt tên cho ID cơ sở dữ liệu của chúng. Thay vào đó, hãy ánh xạ cột đó tới "Mã định danh biện pháp kiểm soát (mã định danh cơ sở dữ liệu, xuất dữ liệu cũ)" hoặc xuất lại các biện pháp kiểm soát để nhận được ID hiển thị. Nếu cột chứa ID từ 1001 trở lên, đó là cột ID hiển thị: hãy đổi tên tiêu đề của nó thành "Mã định danh biện pháp kiểm soát (như hiển thị)" và ánh xạ lại.',
    'ControlIdHeaderIsDisplayed' => 'Không có dữ liệu nào được nhập. Cột được ánh xạ tới "Mã định danh biện pháp kiểm soát (mã định danh cơ sở dữ liệu, xuất dữ liệu cũ)" có tiêu đề là "Mã định danh biện pháp kiểm soát (như hiển thị)", vì vậy nó chứa các ID được hiển thị. Thay vào đó, hãy ánh xạ cột đó tới "Mã định danh biện pháp kiểm soát (như hiển thị)".',
